219	            }
220	        }
221	        return new ResponseEntity<>(HttpStatus.NOT_FOUND);
222	    }
223	
224	    /**
225	     * Resolves the city name to use for a newly created owner. The supplied city is
226	     * title-cased (each whitespace-separated word starts with an upper-case letter and the
227	     * remaining letters are lower-cased), for example {@code "new york"} becomes
228	     * {@code "New York"}. However, if an owner already exists in that city (matched ignoring
229	     * letter case), the existing owner's exact spelling of the city name is reused instead, so
230	     * that all owners in a city share a single canonical spelling.
231	     *
232	     * @param city the city supplied for the owner being created, may be {@code null}
233	     * @return the city name to store and return for the owner
234	     */
235	    private String resolveCity(String city) {
236	        if (city == null) {
237	            return null;
238	        }
239	        String existingCity = this.clinicService.findAllOwners().stream()
240	            .map(Owner::getCity)
241	            .filter(existing -> existing != null && existing.equalsIgnoreCase(city))
242	            .findFirst()
243	            .orElse(null);
244	        if (existingCity != null) {
245	            return existingCity;
246	        }
247	        return toTitleCase(city);
248	    }
249	
250	    /**
251	     * Title-cases the given text so that each whitespace-separated word starts with an
252	     * upper-case letter and the remaining letters are lower-cased, for example
253	     * {@code "new york"} and {@code "NEW YORK"} both become {@code "New York"}. The original
254	     * spacing between words is preserved.
255	     *
256	     * @param value the text to title-case
257	     * @return the title-cased text
258	     */
259	    private static String toTitleCase(String value) {
260	        StringBuilder result = new StringBuilder(value.length());
261	        boolean startOfWord = true;
262	        for (int i = 0; i < value.length(); i++) {
263	            char ch = value.charAt(i);
264	            if (Character.isWhitespace(ch)) {
265	                startOfWord = true;
266	                result.append(ch);
267	            } else if (startOfWord) {
268	                result.append(Character.toUpperCase(ch));
269	                startOfWord = false;
270	            } else {
271	                result.append(Character.toLowerCase(ch));
272	            }
273	        }
274	        return result.toString();
275	    }
276	
277	    /**
278	     * Builds the customer code for a newly created owner, formatted as
279	     * {@code '<UPPERCASE_CITY>-<NNNN>'} where {@code NNNN} is one more than the number of
280	     * owners already registered in that city, zero-padded to four digits (e.g.
281	     * {@code 'LONDON-0007'}). Cities are matched ignoring letter case so the sequence is
282	     * consistent with the upper-cased prefix.
283	     *
284	     * @param city the city of the owner being created
285	     * @return the assigned customer code
286	     */
287	    private String nextCustomerCode(String city) {
288	        long ownersInCity = this.clinicService.findAllOwners().stream()
289	            .filter(existing -> city.equalsIgnoreCase(existing.getCity()))
290	            .count();
291	        return city.toUpperCase() + "-" + String.format("%04d", ownersInCity + 1);
292	    }
293	
294	    /**
295	     * Counts how many existing owners share the given last name at this moment. The count is taken
296	     * over the owners already registered (excluding the owner currently being created, which has not
297	     * yet been persisted); last names are compared for exact equality.
298	     *
299	     * @param lastName the last name of the owner being created
300	     * @return the number of other owners that currently share the given last name
301	     */
302	    private int countNamesakes(String lastName) {
303	        return (int) this.clinicService.findAllOwners().stream()
304	            .filter(existing -> Objects.equals(existing.getLastName(), lastName))
305	            .count();
306	    }
307	
308	    /**
309	     * Determines whether the maximum number of owners that may be registered on a single day has
310	     * already been reached. At most 20 owners may be created per day; the count is taken over the
311	     * owners whose registration date is today.
312	     *
313	     * @return {@code true} if 20 or more owners have already been registered today
314	     */
315	    private boolean isDailyRegistrationLimitReached() {
316	        LocalDate today = LocalDate.now();
317	        long ownersToday = this.clinicService.findAllOwners().stream()
318	            .filter(existing -> today.equals(existing.getRegistrationDate()))
319	            .count();
320	        return ownersToday >= 20;
321	    }
322	
323	    /**
324	     * Determines whether the city of the owner being created has already reached its capacity of
325	     * owners. At most 8 owners may be registered in a single city; the count is taken over the
326	     * existing owners whose city matches (ignoring letter case) the given city.
327	     *
328	     * @param city the city of the owner being created, may be {@code null}
329	     * @return {@code true} if the city already contains 8 or more owners
330	     */
331	    private boolean isCityCapacityReached(String city) {
332	        if (city == null) {
333	            return false;
334	        }
335	        long ownersInCity = this.clinicService.findAllOwners().stream()
336	            .filter(existing -> city.equalsIgnoreCase(existing.getCity()))
337	            .count();
338	        return ownersInCity >= 8;
339	    }
340	
341	    /**
342	     * Determines whether an owner already exists that uses the same telephone number as the
343	     * given candidate. Telephone numbers are compared digits-only, so formatting characters
344	     * such as spaces, dashes and parentheses are ignored.
345	     *
346	     * @param owner the candidate owner to check
347	     * @return {@code true} if an owner with the same telephone number already exists
348	     */
349	    private boolean isDuplicateOwner(Owner owner) {
350	        String telephone = normalizeTelephone(owner.getTelephone());
351	        return this.clinicService.findAllOwners().stream()
352	            .anyMatch(existing -> Objects.equals(normalizeTelephone(existing.getTelephone()), telephone));
353	    }
354	
355	    /**
356	     * Determines whether an owner already exists that uses the same email address as the
357	     * given candidate. Owners without an email address are never considered duplicates.
358	     * The comparison ignores letter case and surrounding or repeated whitespace.
359	     *
360	     * @param owner the candidate owner to check
361	     * @return {@code true} if an owner with the same email address already exists
362	     */
363	    private boolean isDuplicateEmail(Owner owner) {
364	        String email = normalize(owner.getEmail());
365	        if (email == null || email.isEmpty()) {
366	            return false;
367	        }
368	        return this.clinicService.findAllOwners().stream()
369	            .anyMatch(existing -> Objects.equals(normalize(existing.getEmail()), email));
370	    }
371	
372	    /**
373	     * Normalizes a value for duplicate detection so that comparisons ignore letter case and
374	     * surrounding or repeated whitespace. Leading and trailing whitespace is stripped, any run
375	     * of internal whitespace collapses to a single space, and the result is lower-cased. For
376	     * example {@code "  John   Smith "} and {@code "John Smith"} both normalize to
377	     * {@code "john smith"}.
378	     *
379	     * @param value the value to normalize, may be {@code null}
380	     * @return the normalized value, or {@code null} if {@code value} is {@code null}
381	     */
382	    private static String normalize(String value) {
383	        if (value == null) {
384	            return null;
385	        }
386	        return value.strip().replaceAll("\\s+", " ").toLowerCase();
387	    }
388	
389	    /**
390	     * Normalizes a telephone number to digits only by stripping every non-digit character
391	     * (such as spaces, dashes and parentheses). This is used both to store telephone numbers
392	     * in a canonical form and to compare them for uniqueness, so that {@code "(613) 555-0100"}
393	     * and {@code "6135550100"} are treated as the same number.
394	     *
395	     * @param value the telephone number to normalize, may be {@code null}
396	     * @return the digits-only telephone number, or {@code null} if {@code value} is {@code null}
397	     */
398	    private static String normalizeTelephone(String value) {
399	        if (value == null) {
400	            return null;
401	        }
402	        return value.replaceAll("\\D", "");
403	    }
404	}
